/// The Cloud HSM Cluster's auto-generated Domain Name Label Scope
enum AutoGeneratedDomainNameLabelScope {
  valueTenantReuse("TenantReuse"),
  valueSubscriptionReuse("SubscriptionReuse"),
  valueResourceGroupReuse("ResourceGroupReuse"),
  valueNoReuse("NoReuse");

  const AutoGeneratedDomainNameLabelScope(this.value);
  final String value;

  static AutoGeneratedDomainNameLabelScope fromValue(String value) {
    for (final item in AutoGeneratedDomainNameLabelScope.values) {
      if (item.value == value) {
        return item;
      }
    }
    throw ArgumentError('Unknown AutoGeneratedDomainNameLabelScope value: $value');
  }
}

